def is_sublist(l, s):
    # Check if the sublist is empty, return True as an empty list is a sublist of any list
    if not s:
        return True
    # Check if the sublist is longer than the list, return False as it cannot be a sublist
    elif len(s) > len(l):
        return False
    # Iterate through the list to check for the presence of the sublist
    else:
        for i in range(len(l)):
            # If the first element of the sublist matches the current element in the list
            if l[i] == s[0]:
                n = 1
                # Check the subsequent elements to see if they match the sublist
                while (n < len(s)) and (l[i+n] == s[n]):
                    n += 1
                # If all elements match, return True
                if n == len(s):
                    return True
    # If no match is found, return False
    return False

