def max_sum(arr):
    n = len(arr)
    # Initialize the list to store the maximum sum of increasing subsequence
    inc = [0] * n
    # Initialize the list to store the maximum sum of decreasing subsequence
    dec = [0] * n

    # Fill inc[] such that inc[i] contains the maximum sum of increasing subsequence
    # ending with arr[i]
    for i in range(n):
        inc[i] = arr[i]
        for j in range(i):
            if arr[i] > arr[j] and inc[i] < inc[j] + arr[i]:
                inc[i] = inc[j] + arr[i]

    # Fill dec[] such that dec[i] contains the maximum sum of decreasing subsequence
    # starting with arr[i]
    for i in range(n-1, -1, -1):
        dec[i] = arr[i]
        for j in range(i+1, n):
            if arr[i] > arr[j] and dec[i] < dec[j] + arr[i]:
                dec[i] = dec[j] + arr[i]

    # Find the maximum sum of bitonic subsequence
    max_sum = 0
    for i in range(n):
        max_sum = max(max_sum, inc[i] + dec[i] - arr[i])

    return max_sum

def is_Sum_Of_Powers_Of_Two(n):
    # Loop until n becomes 0
    while n:
        # If n is odd and greater than 1, it cannot be represented as sum of non-zero powers of 2
        if n & 1 and n > 1:
            return False
        # Right shift n by 1 to check the next bit
        n >>= 1
    # If the loop completes, n is 0 and the number can be represented as sum of non-zero powers of 2
    return True

