def max_product(arr):
    n = len(arr)
    # Initialize the list to store the maximum product subsequence ending at each index
    max_product_subseq = arr[:]

    # Iterate through the array to fill the max_product_subseq list
    for i in range(1, n):
        for j in range(i):
            # Check if the current element is greater than the element at j and if multiplying
            # max_product_subseq[j] with arr[i] gives a larger product than max_product_subseq[i]
            if arr[i] > arr[j] and max_product_subseq[i] < max_product_subseq[j] * arr[i]:
                max_product_subseq[i] = max_product_subseq[j] * arr[i]

    # Return the maximum value from the max_product_subseq list
    return max(max_product_subseq)

