def next_power_of_2(n):
    # If n is less than or equal to 1, return 1 as the smallest power of 2
    if n <= 1:
        return 1
    # Calculate the power of 2 greater than or equal to n
    power = 2
    while power < n:
        power *= 2
    return power

def occurance_substring(text, pattern):
    # Find the starting index of the first occurrence of the pattern
    start = text.find(pattern)
    # If the pattern is not found, return None
    if start == -1:
        return None
    # Calculate the end index of the first occurrence
    end = start + len(pattern)
    # Return the pattern and its start and end positions
    return (pattern, start, end)

def check_occurences(test_list):
    # Initialize an empty dictionary to store the count of each tuple
    res_dict = {}

    # Iterate over each tuple in the test list
    for sub in test_list:
        # If the tuple is already in the dictionary, increment its count
        if sub in res_dict:
            res_dict[sub] += 1
        # If the tuple is not in the dictionary, add it with a count of 1
        else:
            res_dict[sub] = 1

    # Return the dictionary containing the count of each tuple
