def second_smallest(numbers):
    # Initialize the smallest and second smallest to positive infinity
    smallest = second_smallest = float('inf')

    # Iterate through each number in the list
    for num in numbers:
        # Update the smallest and second smallest values
        if num <= smallest:
            smallest, second_smallest = num, smallest
        elif num < second_smallest:
            second_smallest = num

    # Return the second smallest number found
